/**
 * components/ExplanationPanel.js
 * AI-generated natural language explanation of the prediction.
 * Calls Claude API to generate a rich narrative on the fly.
 */

import React, { useState, useEffect } from 'react';
import './ExplanationPanel.css';

/* Small spinner used while Claude generates */
function Thinking() {
  return (
    <div className="exp-thinking">
      <span className="spin-sm" />
      <span>ATHENA is generating analysis…</span>
    </div>
  );
}

/* Render explanation text — highlight key values */
function ExplBody({ text }) {
  if (!text) return null;
  return (
    <div className="exp-body">
      {text.split('\n').map((line, i) => {
        if (!line.trim()) return <div key={i} className="exp-spacer" />;
        if (line.startsWith('📊') || line.startsWith('🔑') || line.startsWith('🏆'))
          return <div key={i} className="exp-section">{line}</div>;
        if (line.startsWith('  •') || line.startsWith('  '))
          return <div key={i} className="exp-line">{line}</div>;
        return <div key={i} className="exp-para">{line}</div>;
      })}
    </div>
  );
}

export default function ExplanationPanel({ prediction }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!prediction) return;
    generate(prediction);
  }, [prediction?.ticker, prediction?.predicted_price]);   // re-run per new prediction

  async function generate(p) {
    setLoading(true);
    setText('');
    try {
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 280,
          messages: [{
            role: 'user',
            content: `You are ATHENA, an explainable AI financial analyst.
Write a concise 3-sentence analysis of this stock prediction.
Use plain text only — no markdown, no bullet symbols, no asterisks.
Mention the market regime, the top SHAP feature, and the confidence level naturally in the text.

Stock: ${p.ticker}
Current: $${p.current_price?.toFixed(2)} → Predicted: $${p.predicted_price?.toFixed(2)} (${p.change_percent >= 0 ? '+' : ''}${p.change_percent?.toFixed(2)}%)
Direction: ${p.direction?.replace(/[^A-Z]/g, '') || 'UP'}
Market Regime: ${p.regime?.regime_name || p.regime?.name || 'Trending'}
Confidence: ${((p.confidence || 0) * 100).toFixed(1)}%
Top SHAP feature: ${p.top_features?.[0]?.name || 'RSI_14'} (${(p.top_features?.[0]?.impact || 0) > 0 ? 'bullish' : 'bearish'})
Second feature: ${p.top_features?.[1]?.name || 'MACD_Signal'}`
          }]
        })
      });
      const data = await res.json();
      setText(data.content?.[0]?.text || fallback(p));
    } catch {
      setText(fallback(p));
    } finally {
      setLoading(false);
    }
  }

  function fallback(p) {
    const regime  = p.regime?.regime_name || p.regime?.name || 'Trending';
    const top     = p.top_features?.[0];
    const dir     = (p.direction || '').includes('UP') ? 'upward' : 'downward';
    return `The LSTM-Attention model analysed ${p.ticker}'s 60-day historical window and detected a ${regime.toLowerCase()} market regime. `
      + `${top ? `The primary driver is ${top.name}, contributing a ${top.impact > 0 ? 'bullish' : 'bearish'} signal with a SHAP impact of ${top.impact?.toFixed(4)}.` : ''} `
      + `An ${dir} move to $${p.predicted_price?.toFixed(2)} is projected with ${((p.confidence || 0) * 100).toFixed(1)}% adjusted confidence after regime correction.`;
  }

  return (
    <div className="exp-panel">
      <div className="exp-header">
        <div className="exp-ico cyan">🤖</div>
        <div className="exp-title">AI-Generated Analysis</div>
        <span className="exp-badge">CLAUDE · LSTM · SHAP · REGIME</span>
      </div>

      {loading ? <Thinking /> : <ExplBody text={text} />}

      <div className="exp-disclaimer">
        ⚠️ Research tool only. Not financial advice. ~54–80% directional accuracy depending on market conditions.
        Always consult a qualified financial advisor before making investment decisions.
      </div>
    </div>
  );
}
